cases.originalCaseSource:
it.each([
    { name: 'null Decimal128 bytes', create: () => Object.assign(bson.Decimal128.fromString('1.2'), { bytes: null }) },
    {
      name: 'missing ObjectId serializer',
      create: () => Object.assign(new bson.ObjectId(hex), { serializeInto: null }),
    },
    {
      name: 'wrong BSON version',
      create: () => Object.defineProperty(new bson.Long(1, 2), Symbol.for('@@mdb.bson.version'), { value: -1 }),
    },
  ])('does not bypass serializer rejection of $name', ({ create }) => {
    const source = create();
    expect(() => roundTrip(source)).toThrow();
    const serialize = vi.spyOn(mongo.BSON, 'serialize');
    expectAuthorizationError(() => copyAuthorizationValue(source), 'unsupported BSON snapshot');
    expect(serialize).toHaveBeenCalledTimes(1);
  })

it("retains wire normalization/rejection for malformed ObjectId words or the other BSON version's storage layout", () => {
    const malformed = new bson.ObjectId(hex);
    const words = Object.hasOwn(malformed, 'i0');
    if (words) Object.assign(malformed, { i0: 0x1000000 + 0x123456, i1: 1.5, i2: -1, i3: NaN });
    else Object.assign(malformed, { buffer: Buffer.alloc(11) });
    const otherLayout = new bson.ObjectId(hex);
    for (const key of Reflect.ownKeys(otherLayout)) Reflect.deleteProperty(otherLayout, key);
    Object.assign(otherLayout, words ? { buffer: Buffer.alloc(12, 1) } : { i0: 1, i1: 2, i2: 3, i3: 4 });
    for (const source of [malformed, otherLayout]) {
      let expected: unknown;
      let rejected = false;
      try {
        expected = roundTrip(source);
      } catch {
        rejected = true;
      }
      const serialize = vi.spyOn(mongo.BSON, 'serialize');
      if (rejected) expect(() => copyAuthorizationValue(source)).toThrow(ServiceAuthorizationError);
      else expect(isDeepStrictEqual(copyAuthorizationValue(source), expected)).toBe(true);
      expect(serialize).toHaveBeenCalledTimes(1);
      serialize.mockRestore();
    }
  })

it.each(['id', 'decimal', 'long'] as const)('invokes %s own accessors only as required by serialization', (kind) => {
    const source =
      kind === 'id'
        ? new bson.ObjectId(hex)
        : kind === 'decimal'
          ? bson.Decimal128.fromString('1.2')
          : new bson.Long(1, 2);
    const key = kind === 'id' ? Reflect.ownKeys(source)[0] : kind === 'decimal' ? 'bytes' : 'low';
    const value = Object.getOwnPropertyDescriptor(source, key)!.value;
    const getter = vi.fn(() => value);
    Object.defineProperty(source, key, { enumerable: true, configurable: true, get: getter });
    const expected = roundTrip(source);
    const calls = getter.mock.calls.length;
    expect(calls).toBeGreaterThan(0);
    getter.mockClear();
    const serialize = vi.spyOn(mongo.BSON, 'serialize');
    expect(isDeepStrictEqual(copyAuthorizationValue(source), expected)).toBe(true);
    expect(getter).toHaveBeenCalledTimes(calls);
    expect(serialize).toHaveBeenCalledTimes(1);
  })

it.each(['id', 'decimal', 'long'] as const)('does not inspect extra %s own native getters', (kind) => {
    const source =
      kind === 'id'
        ? new bson.ObjectId(hex)
        : kind === 'decimal'
          ? bson.Decimal128.fromString('1.2')
          : new bson.Long(1, 2);
    const getter = vi.fn(() => {
      throw new Error('must not inspect extra native fields');
    });
    Object.defineProperty(source, 'extra', { get: getter });
    const expected = roundTrip(source);
    const serialize = vi.spyOn(mongo.BSON, 'serialize');
    expect(isDeepStrictEqual(copyAuthorizationValue(source), expected)).toBe(true);
    expect(getter).not.toHaveBeenCalled();
    expect(serialize).toHaveBeenCalledTimes(1);
  })

it('preserves wire semantics without reading an application byteLength accessor', () => {
    const source = bson.Decimal128.fromString('1.2');
    const getter = vi.fn(() => {
      throw new Error('must not inspect byteLength');
    });
    Object.defineProperty(source.bytes, 'byteLength', { get: getter });
    const expected = roundTrip(source);
    const serialize = vi.spyOn(mongo.BSON, 'serialize');
    expect(isDeepStrictEqual(copyAuthorizationValue(source), expected)).toBe(true);
    expect(getter).not.toHaveBeenCalled();
    expect(serialize).toHaveBeenCalledTimes(1);
  })

it('retains inherited toBSON normalization without extra accessor calls', () => {
    const getter = vi.fn(() => () => new bson.Int32(321));
    try {
      Object.defineProperty(bson.Long.prototype, 'toBSON', { configurable: true, get: getter });
      const source = new bson.Long(1, 2);
      const expected = roundTrip(source);
      const calls = getter.mock.calls.length;
      getter.mockClear();
      const serialize = vi.spyOn(mongo.BSON, 'serialize');
      expect(isDeepStrictEqual(copyAuthorizationValue(source), expected)).toBe(true);
      expect(getter).toHaveBeenCalledTimes(calls);
      expect(serialize).toHaveBeenCalledTimes(1);
    } finally {
      Reflect.deleteProperty(bson.Long.prototype, 'toBSON');
    }
  })

it('does not bypass changed prototype wire methods or invoke their accessors twice', () => {
    const descriptor = Object.getOwnPropertyDescriptor(bson.Long.prototype, 'getLowBits')!;
    const getter = vi.fn(() => () => 123);
    try {
      Object.defineProperty(bson.Long.prototype, 'getLowBits', { configurable: true, get: getter });
      const source = new bson.Long(1, 2);
      const expected = roundTrip(source);
      const calls = getter.mock.calls.length;
      getter.mockClear();
      const serialize = vi.spyOn(mongo.BSON, 'serialize');
      expect(isDeepStrictEqual(copyAuthorizationValue(source), expected)).toBe(true);
      expect(getter).toHaveBeenCalledTimes(calls);
      expect(serialize).toHaveBeenCalledTimes(1);
    } finally {
      Object.defineProperty(bson.Long.prototype, 'getLowBits', descriptor);
    }
  })

it('retains serializer validation of a changed inherited BSON version getter', () => {
    const version = Symbol.for('@@mdb.bson.version');
    const descriptor = Object.getOwnPropertyDescriptor(bson.BSONValue.prototype, version)!;
    const getter = vi.fn(() => -1);
    try {
      Object.defineProperty(bson.BSONValue.prototype, version, { configurable: true, get: getter });
      const source = new bson.Long(1, 2);
      expect(() => roundTrip(source)).toThrow();
      const calls = getter.mock.calls.length;
      expect(calls).toBeGreaterThan(0);
      getter.mockClear();
      const serialize = vi.spyOn(mongo.BSON, 'serialize');
      expectAuthorizationError(() => copyAuthorizationValue(source), 'unsupported BSON snapshot');
      expect(getter).toHaveBeenCalledTimes(calls);
      expect(serialize).toHaveBeenCalledTimes(1);
    } finally {
      Object.defineProperty(bson.BSONValue.prototype, version, descriptor);
    }
  })

it.each(['Long bits', 'ObjectId bytes', 'BSON version'] as const)(
    'retains wire overrides installed before the snapshot module loaded: %s',
    async (kind) => {
      const prototype =
        kind === 'Long bits'
          ? bson.Long.prototype
          : kind === 'ObjectId bytes'
            ? bson.ObjectId.prototype
            : bson.BSONValue.prototype;
      const key =
        kind === 'Long bits'
          ? 'getLowBits'
          : kind === 'ObjectId bytes'
            ? 'serializeInto'
            : Symbol.for('@@mdb.bson.version');
      const descriptor = Object.getOwnPropertyDescriptor(prototype, key)!;
      try {
        Object.defineProperty(
          prototype,
          key,
          kind === 'BSON version'
            ? { ...descriptor, get: () => -1 }
            : {
                ...descriptor,
                value:
                  kind === 'Long bits'
                    ? () => 123
                    : (buffer: Uint8Array, index: number) => {
                        buffer.set(Buffer.alloc(12, 0x12), index);
                        return 12;
                      },
              },
        );
        vi.resetModules();
        const isolated = await import('../src/acl/authorization-snapshot');
        const source = kind === 'ObjectId bytes' ? new bson.ObjectId(hex) : new bson.Long(1, 2);
        if (kind === 'BSON version') {
          expect(() => roundTrip(source)).toThrow();
          expect(() => isolated.copyAuthorizationValue(source)).toThrow(isolated.ServiceAuthorizationError);
          expect(isolated.matchesAuthorizationSnapshot(source, source)).toBe(false);
        } else {
          const expected = roundTrip(source);
          expect(isDeepStrictEqual(isolated.copyAuthorizationValue(source), expected)).toBe(true);
          expect(isolated.matchesAuthorizationSnapshot({ source }, { source: expected })).toBe(true);
        }
      } finally {
        Object.defineProperty(prototype, key, descriptor);
        vi.resetModules();
      }
    },
  )

it('handles null/plain records through descriptors, not BSON-looking properties or application accessors', () => {
    const input = Object.assign(Object.create(null), { value: new bson.ObjectId(hex), _bsontype: 'ObjectId' });
    expect(copyAuthorizationValue(input)).toEqual({ value: new bson.ObjectId(hex), _bsontype: 'ObjectId' });
    expect(copyAuthorizationValue(null)).toBeNull();
    const getter = vi.fn(() => new bson.ObjectId(hex));
    for (const mode of [false, true, 'document'] as const) {
      expect(() =>
        copyAuthorizationValue(Object.defineProperty({}, 'value', { enumerable: true, get: getter }), mode),
      ).toThrow(ServiceAuthorizationError);
      expect(() => copyAuthorizationValue({ value: Object.create({ id: new bson.ObjectId(hex) }) }, mode)).toThrow(
        ServiceAuthorizationError,
      );
    }
    expect(getter).not.toHaveBeenCalled();
  })

it('retains non-enumerable data handling, unsafe-key/cycle rejection and structural limits around BSON leaves', () => {
    const hidden = Object.defineProperty({}, 'value', { value: new bson.ObjectId(hex) });
    expectAuthorizationError(() => copyAuthorizationValue(hidden), 'accessor/non-enumerable input');
    expect(copyAuthorizationValue(hidden, 'document')).toEqual({ value: new bson.ObjectId(hex) });
    expectAuthorizationError(() => copyAuthorizationValue(JSON.parse('{"__proto__":{}}')), 'unsafe snapshot key');
    const cyclic: Record<string, unknown> = { id: new bson.ObjectId(hex) };
    cyclic.self = cyclic;
    expectAuthorizationError(() => copyAuthorizationValue(cyclic), 'cyclic input');
    let nested: unknown = new bson.Long(1, 2);
    for (let depth = 0; depth < 101; depth++) nested = { nested };
    expectAuthorizationError(() => copyAuthorizationValue(nested), 'snapshot exceeds structural limits');
    expectAuthorizationError(
      () => copyAuthorizationValue(Array(20001).fill(new bson.Long(1, 2))),
      'snapshot array exceeds structural limits',
    );
    expectAuthorizationError(
      () => copyAuthorizationValue(Array(20000).fill(new bson.Long(1, 2))),
      'snapshot exceeds structural limits',
    );
  })

it('removes per-record-property descriptor materialization without dropping array definitions or freezes', () => {
    const value = {
      rows: [
        { a: 1, b: 2 },
        { a: 3, b: 4 },
      ],
      meta: { visible: true },
    };
    const definitions = vi.spyOn(Object, 'defineProperty');
    const before = legacy(value, 'document');
    expect(definitions).toHaveBeenCalledTimes(9);
    definitions.mockClear();
    const after = copyAuthorizationValue(value, 'document');
    expect(definitions).toHaveBeenCalledTimes(2); // Sparse/numeric array semantics retain the old builder.
    expect(after).toEqual(before);
    expect([after, after.rows, ...after.rows, after.meta].every(Object.isFrozen)).toBe(true);
  })

it('agrees with the independent original copier on 512 seeded graphs in all three modes', () => {
    const primitives = [null, undefined, false, true, NaN, -0, 12n, '雪'];
    for (let seed = 1; seed <= 512; seed++) {
      let state = seed;
      const next = () => (state = (Math.imul(state, 1664525) + 1013904223) >>> 0);
      const aliases: unknown[] = [];
      function generate(depth: number): unknown {
        if (!depth || next() % 4 === 0) return primitives[next() % primitives.length];
        if (aliases.length && next() % 7 === 0) return aliases[next() % aliases.length];
        const array = next() % 2 === 0;
        const value = array ? Array(next() % 5) : Object.create(next() % 2 ? Object.prototype : null);
        for (let index = 0, length = array ? value.length : next() % 5; index < length; index++) {
          if (array && next() % 3 === 0) continue;
          Object.defineProperty(value, array ? String(index) : `field${index}`, {
            value: generate(depth - 1),
            enumerable: next() % 3 !== 0,
          });
        }
        aliases.push(value);
        return value;
      }
      const source = generate(4);
      for (const mode of [false, true, 'document'] as const)
        expect(outcome(copyAuthorizationValue, source, mode)).toEqual(outcome(legacy, source, mode));
    }
  })

it('does not invoke inherited setters and publishes normal-prototype frozen data properties', () => {
    const key = 'pipe02InheritedSetter';
    const setter = vi.fn(() => {
      throw new Error('inherited setter must not run');
    });
    const previous = Object.getOwnPropertyDescriptor(Object.prototype, key);
    try {
      Object.defineProperty(Object.prototype, key, { configurable: true, set: setter });
      const source = Object.defineProperty(Object.create(null), key, { value: { nested: 1 }, enumerable: true });
      const value = copyAuthorizationValue(source, 'document');
      expect(Object.getPrototypeOf(value)).toBe(Object.prototype);
      expect(Object.getOwnPropertyDescriptor(value, key)).toEqual({
        value: { nested: 1 },
        enumerable: true,
        writable: false,
        configurable: false,
      });
      expect(setter).not.toHaveBeenCalled();
    } finally {
      if (previous) Object.defineProperty(Object.prototype, key, previous);
      else Reflect.deleteProperty(Object.prototype, key);
    }
  })

it('rechecks inherited keys after native normalization installs a setter', () => {
    const key = 'pipe02DuringNormalization';
    const setter = vi.fn(() => {
      throw new Error('new inherited setter must not run');
    });
    const previous = Object.getOwnPropertyDescriptor(Object.prototype, key);
    try {
      const native = Object.assign(new mongo.BSON.ObjectId(), {
        toBSON() {
          Object.defineProperty(Object.prototype, key, { configurable: true, set: setter });
          return 'normalized';
        },
      });
      const source = { [key]: native };
      const value = copyAuthorizationValue(source, 'document');
      expect(value[key]).toBe('normalized');
      expect(setter).not.toHaveBeenCalled();
      expect(Object.getOwnPropertyDescriptor(value, key)).toEqual({
        value: 'normalized',
        enumerable: true,
        writable: false,
        configurable: false,
      });
    } finally {
      if (previous) Object.defineProperty(Object.prototype, key, previous);
      else Reflect.deleteProperty(Object.prototype, key);
    }
  })

it('does not traverse a target prototype replaced during recursive native work', () => {
    const run = (copy: typeof legacy) => {
      let target: object | undefined;
      const has = vi.fn(() => {
        throw new Error('must not inspect replaced prototype');
      });
      const prototype = new Proxy({}, { has });
      const define = Object.defineProperty;
      const spy = vi.spyOn(Object, 'defineProperty').mockImplementation((object, key, descriptor) => {
        if (key === 'toString') target = object;
        return define(object, key, descriptor);
      });
      try {
        const source = {
          toString: 'data',
          when: Object.assign(new Date(1), {
            getTime() {
              Object.setPrototypeOf(target!, prototype);
              return 1;
            },
          }),
        };
        const value = copy(source, 'document');
        expect(Object.getPrototypeOf(value)).toBe(prototype);
        expect(Object.getOwnPropertyDescriptor(value, 'when')?.value).toEqual(new Date(1));
        expect(has).not.toHaveBeenCalled();
      } finally {
        spy.mockRestore();
      }
    };
    run(legacy);
    run(copyAuthorizationValue);
  })

it.each([false, true, 'document'] as const)('retains wire/native/proxy observation order in mode %s', (mode) => {
    const run = (copy: typeof legacy) => {
      const events: string[] = [];
      const source: Record<string, unknown> = { first: 'before' };
      source.date = Object.assign(new Date(1), {
        getTime() {
          events.push('date');
          return 1;
        },
      });
      source.native = Object.assign(new mongo.BSON.ObjectId('0123456789abcdef01234567'), {
        toBSON() {
          events.push('wire');
          source.first = 'changed';
          source.later = 'changed later';
          return 'normalized';
        },
      });
      source.proxy = new Proxy(
        { value: 1 },
        {
          getPrototypeOf(target) {
            events.push('prototype');
            return Reflect.getPrototypeOf(target);
          },
          ownKeys(target) {
            events.push('keys');
            return Reflect.ownKeys(target);
          },
          getOwnPropertyDescriptor(target, key) {
            events.push(`descriptor:${String(key)}`);
            return Reflect.getOwnPropertyDescriptor(target, key);
          },
        },
      );
      source.later = 'before';
      return { result: outcome(copy, source, mode), events, final: source.first };
    };
    expect(run(copyAuthorizationValue)).toEqual(run(legacy));
  })

it('keeps independent aliases, mutable leaves, Map/Set normalization and configuration functions', () => {
    const shared = { when: new Date(1), bytes: Buffer.from([1]), id: new mongo.BSON.ObjectId() };
    const fn = () => true;
    const source = { first: shared, second: shared, map: new Map([[shared, shared]]), set: new Set([shared]), fn };
    const value = copyAuthorizationValue(source, true);
    expect(isDeepStrictEqual(value, legacy(source, true))).toBe(true);
    expect(value.first).not.toBe(value.second);
    expect(value.first.when).not.toBe(value.second.when);
    expect(value.fn).toBe(fn);
    value.first.when.setTime(9);
    value.first.bytes[0] = 9;
    expect(value.second.when.getTime()).toBe(1);
    expect(value.second.bytes[0]).toBe(1);
    expect(shared.when.getTime()).toBe(1);
  })

it('agrees on 512 deterministic generated graphs, changed sources and changed snapshots', () => {
    const primitives = [null, undefined, false, true, 0, -0, NaN, Infinity, -Infinity, 123n, '', '雪'];
    for (let seed = 1; seed <= 512; seed++) {
      let state = seed;
      const next = () => (state = (Math.imul(state, 1664525) + 1013904223) >>> 0);
      const aliases: unknown[] = [];
      function generate(depth: number): unknown {
        if (!depth || next() % 4 === 0) return primitives[next() % primitives.length];
        if (aliases.length && next() % 7 === 0) return aliases[next() % aliases.length];
        let result: any;
        if (next() % 2) {
          result = Array(next() % 6);
          for (let i = 0; i < result.length; i++) {
            if (next() % 3)
              Object.defineProperty(result, String(i), { value: generate(depth - 1), enumerable: !!(next() % 2) });
          }
        } else {
          result = Object.create(next() % 2 ? Object.prototype : null);
          for (let i = 0, count = next() % 5; i < count; i++) {
            Object.defineProperty(result, `${next() % 2 ? 'field' : '雪'}${i}`, {
              value: generate(depth - 1),
              enumerable: !!(next() % 2),
            });
          }
        }
        if (next() % 3 === 0) Object.freeze(result);
        aliases.push(result); // Only completed nodes: shared aliases, never active cycles.
        return result;
      }
      const source = { payload: generate(4), stable: 'original' };
      const snapshot = copyAuthorizationValue(source, 'document');
      agrees(source, snapshot, true);
      agrees(source, { ...snapshot, stable: 'different' }, false);
      source.stable = 'changed';
      agrees(source, snapshot, false);
    }
  })

