      snapshot[index] = 2;
      Object.defineProperty(value, key, { value: 'extra', enumerable: shape !== 'hidden source' });
      Object.defineProperty(snapshot, key, {
        enumerable: true,
        get() {
          events.push('extra');
          snapshot[index] = 1;
          return 'extra';
        },
      });
      return {
        value: shape === 'nested' ? { rows: [{ value }] } : value,
        snapshot: shape === 'nested' ? { rows: [{ value: snapshot }] } : snapshot,
